import React, { useEffect, useRef, useState } from "react";
import FileUploadIcon from "@mui/icons-material/FileUpload";
import EditIcon from "@mui/icons-material/Edit";
import ActorList from "../../assets/all_about_fitness/actor_list.png";
import AddIcon from "@mui/icons-material/Add";
import http, { uploadImage } from "../../services/utility";
import { apisPath } from "../../utils/path";
import { useDispatch } from "react-redux";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";

export default function AllAboutFitness() {
  const dispatch = useDispatch();
  const uploadPdfRef = useRef(null);
  const uploadActorRef = useRef(null);

  const [formData, setFormData] = useState({
    images: [],
    description: "",
    actors: [
      {
        images: [],
        name: "",
        description: "",
      },
    ],
  });

  const [actorList, setActorList] = useState([]);
  const [updateDataInit, setUpdateDataInit] = useState(false);

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    await http
      .get(apisPath?.admin?.aboutFitness)
      .then(async (res) => {
        // console.log(res?.data);
        var data = res?.data?.aboutFitnessList;
        setActorList(data);
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const uploadData = async () => {
    await http
      .post(apisPath?.admin?.aboutFitness, formData)
      .then((res) => {
        // console.log(res);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        setFormData({
          images: [],
          description: "",
          actors: [
            {
              images: [],
              name: "",
              description: "",
            },
          ],
        });
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const deleteData = async (index) => {
    await http
      .delete(`${apisPath?.admin?.aboutFitness}/${index}`)
      .then(async (res) => {
        // console.log(res?.data?.message);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const updateData = async () => {
    let data = {
      images: formData?.images,
      description: formData?.description,
      actors: formData?.actors,
    };
    await http
      .put(`${apisPath?.admin?.aboutFitness}/${formData?.id}`, data)
      .then((res) => {
        // console.log(res);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        setFormData({
          images: [],
          description: "",
          actors: [
            {
              images: [],
              name: "",
              description: "",
            },
          ],
        });
        setUpdateDataInit(false);
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  return (
    <div className="all_about_fitness">
      <h3 className="all_about_fitness__heading page_heading">
        All about fitness
      </h3>
      <div className="all_about_fitness__content">
        <div className="all_about_fitness__content__upload">
          <div
            className="all_about_fitness__content__upload__logo"
            onClick={() => uploadPdfRef?.current?.click()}
          >
            <FileUploadIcon />
            <span>Upload banner</span>
          </div>
          <input
            type="file"
            style={{ display: "none" }}
            ref={uploadPdfRef}
            onChange={async (e) => {
              await uploadImage(e)
                .then((res) => {
                  let data = { ...formData };
                  data?.images?.push(res?.url);
                  setFormData(data);
                })
                .catch((err) => {
                  console.log(err);
                });
            }}
          />
          {formData?.images?.map((image, index) => {
            return (
              <div
                className="all_about_fitness__content__upload__image"
                key={index}
              >
                <img src={image} alt="fitness" />
              </div>
            );
          })}
        </div>

        <div className="all_about_fitness__content__description">
          <label htmlFor="description">Description</label>
          <textarea
            id="description"
            name="description"
            cols="100"
            rows="10"
            value={formData?.description}
            placeholder="Enter here"
            onChange={(el) => {
              let data = { ...formData };
              data.description = el?.target?.value;
              setFormData(data);
            }}
          ></textarea>
          {/* <button className="button-border-red">
            <EditIcon /> Edit
          </button> */}
        </div>

        <hr />

        {formData?.actors?.map((actor, index) => {
          return (
            <div
              className="all_about_fitness__content__bottom_content"
              key={index}
            >
              <h4 className="all_about_fitness__heading page_subheading">
                Actor
              </h4>
              <div className="all_about_fitness__content__bottom_content__content">
                <div className="all_about_fitness__content__upload all_about_fitness__content__bottom_content__content__upload">
                  <div
                    className="all_about_fitness__content__upload__logo all_about_fitness__content__bottom_content__content__upload__logo"
                    onClick={() => uploadActorRef?.current?.click()}
                  >
                    <FileUploadIcon />
                    <span>Upload Actor photo</span>
                  </div>
                  <input
                    type="file"
                    style={{ display: "none" }}
                    ref={uploadActorRef}
                    onChange={async (e) => {
                      await uploadImage(e)
                        .then((res) => {
                          let data = { ...formData };
                          data?.actors[index]?.images?.push(res?.url);
                          setFormData(data);
                        })
                        .catch((err) => {
                          console.log(err);
                        });
                    }}
                  />
                  {actor?.images?.map((image, imageIndex) => {
                    return (
                      <div
                        className="all_about_fitness__content__upload__image"
                        key={imageIndex}
                      >
                        <img src={image} alt="actor" />
                      </div>
                    );
                  })}
                </div>
              </div>

              <input
                type="text"
                id="name"
                name="name"
                value={actor?.name}
                placeholder="Actor name"
                onChange={(el) => {
                  let data = { ...formData };
                  data.actors[index].name = el?.target?.value;
                  setFormData(data);
                }}
              />

              <div className="all_about_fitness__content__bottom_content__description">
                <label htmlFor="description">Description</label>
                <textarea
                  id="description"
                  name="description"
                  cols="100"
                  rows="10"
                  placeholder="Enter here"
                  value={actor?.description}
                  onChange={(el) => {
                    let data = { ...formData };
                    data.actors[index].description = el?.target?.value;
                    setFormData(data);
                  }}
                ></textarea>
              </div>
            </div>
          );
        })}
        <div className="all_about_fitness__content__bottom_content__buttons">
          <button
            className="button-border-red"
            onClick={(e) => {
              let data = { ...formData };
              data?.actors?.push({
                images: [],
                name: "",
                description: "",
              });
              setFormData(data);
            }}
          >
            <AddIcon /> Add more actor
          </button>
          {updateDataInit ? (
            <button className="button-red" onClick={updateData}>
              Update Data
            </button>
          ) : (
            <button className="button-red" onClick={uploadData}>
              Done
            </button>
          )}
        </div>
      </div>
      <div className="all_about_fitness__actor_list">
        <h4 className="all_about_fitness__heading page_subheading">
          Actor list
        </h4>
        <div className="all_about_fitness__actor_list__content">
          {actorList?.length > 0 ? (
            actorList?.map((actor, index) => {
              return (
                <ActorListCard
                  data={actor}
                  deleteData={deleteData}
                  key={index}
                  editData={() => {
                    setFormData(actor);
                    setUpdateDataInit(true);
                  }}
                />
              );
            })
          ) : (
            <div className="no_data_found">No Data Found</div>
          )}
        </div>
      </div>
    </div>
  );
}

const ActorListCard = ({ data, deleteData, editData }) => {
  return (
    <div className="actor_list_card">
      <div
        className="actor_list_card__top_content"
        style={{
          background: `rgba(0,0,0,0.2) url("${
            data?.images?.length > 0 && data?.images[0]
          }") center / cover no-repeat`,
        }}
      ></div>
      <button className="button-border-red" onClick={editData}>
        Edit
      </button>
      <button className="button-red" onClick={() => deleteData(data?.id)}>
        Delete
      </button>
    </div>
  );
};
